"""Building and searching the clinical corpus, for the interface layer."""

from pathlib import Path
from typing import Any

import yaml

DEFAULT_CORPUS_PATH = Path("data/knowledge/corpus.yaml")

_HEADER = """# corpus.yaml
#
# GENERATED by `wha corpus build`. Do not hand-edit: change the source.
#
# Every passage here is rendered from the knowledge tables in this
# repository: data/knowledge/causes.yaml, data/knowledge/red_flags.yaml,
# data/knowledge/probes.yaml and src/wha/constants.py. No clinical content
# is written by the agent, and no external source is fetched.
#
# The citations behind these passages were checked against the published
# papers. What held up and what did not is in docs/CORPUS-VERIFICATION.md.
#
# Layer 1, consumer health information, is NOT in this file. It is MedlinePlus,
# fetched with `wha data fetch corpus`, and the snapshot in use is recorded in
# data/knowledge/corpus-sources.json with its checksum.

"""


def build_corpus_file(out_path: Path | None = None) -> tuple[Path, dict[int, int]]:
    """Render the corpus to YAML so a human can read what the agent may cite.

    The running system does not read this file. It builds the same documents in memory
    from the knowledge tables. The file exists so the passages behind a clinical claim
    can be reviewed and diffed rather than taken on trust.

    Returns the path written and a count of documents per layer.
    """
    from wha.retrieve.knowledge_docs import build_default_corpus

    target = out_path if out_path is not None else DEFAULT_CORPUS_PATH

    # Layer 1 is deliberately excluded. It is MedlinePlus, fetched rather than authored,
    # a thousand topics we do not own and should not redistribute inside this repository.
    # Which snapshot is in use is recorded in data/knowledge/corpus-sources.json instead,
    # with its checksum, which is the part that actually needs to be checkable.
    docs = [d for d in build_default_corpus() if d.layer != 1]
    payload = {"documents": [d.model_dump() for d in docs]}

    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(
        _HEADER + yaml.safe_dump(payload, sort_keys=False, allow_unicode=True, width=88),
        encoding="utf-8",
    )

    by_layer: dict[int, int] = {}
    for doc in docs:
        by_layer[doc.layer] = by_layer.get(doc.layer, 0) + 1
    return target, by_layer


def search_corpus(query: str, top_k: int = 5) -> list[dict[str, Any]]:
    """Search the corpus exactly as the agent's retrieval tool does."""
    from wha.retrieve.knowledge_docs import get_default_index

    results = get_default_index().query(query, top_k=top_k)
    return [
        {
            "rank": r.rank,
            "chunk_id": r.chunk_id,
            "title": r.title,
            "layer": r.layer,
            "score": r.score,
            "text": " ".join(r.text.split()),
        }
        for r in results
    ]
